import openpyxl
import pyreadr
import pandas as pd

# Load PWT data
result = pyreadr.read_r('/root/pwt10/data/pwt10.01.rda')
df_pwt = result['pwt10.01']
geo_pwt = df_pwt[df_pwt['isocode'] == 'GEO']

# Create a dict of PWT data
pwt_rnna = {}
pwt_rgdpna = {}
for _, row in geo_pwt.iterrows():
    yr = int(row['year'])
    if yr >= 1990:
        if not pd.isna(row['rnna']):
            pwt_rnna[yr] = round(float(row['rnna']), 2)
        if not pd.isna(row['rgdpna']):
            pwt_rgdpna[yr] = round(float(row['rgdpna']), 2)

print("PWT rnna data (1990-2019):")
for yr in range(1990, 2020):
    print(f"  {yr}: {pwt_rnna.get(yr, 'N/A')}")

print("\nPWT rgdpna data (1990-2019):")
for yr in range(1990, 2020):
    print(f"  {yr}: {pwt_rgdpna.get(yr, 'N/A')}")
PYEOF
